function mergeSettings(defaults, overrides) {
  return { ...defaults, ...overrides };
}

function countExtras(first, ...rest) {
  return rest.length;
}

console.log(mergeSettings({ volume: 50, muted: false }, { volume: 80 }));
console.log(countExtras("a", "b", "c", "d"));

